// Dial demo: a small Xtream Codes endpoint for the demo playlist (Cloudflare Worker, free plan).
// Generated by tools/generate.py (step "worker") from tools/sources.json; edit the template, not worker.js.
// Videos live in GitHub Releases, artwork on GitHub Pages; this Worker only answers the API, builds the live
// HLS playlists (a sliding window over each channel's loop, so channels behave like live TV) and the TV guide
// (30-minute blocks, built for the current date, so it never expires).
// Account: username "demo", password "demo".

const DATA = __DATA__;

const USERNAME = "demo";
const PASSWORD = "demo";
const SEGMENT_WINDOW = 6;
const BLOCK_SECONDS = 1800;
const GUIDE_DAYS_BEFORE = 1;
const GUIDE_DAYS_AFTER = 3;
// Every NEW_EVERY-th channel, movie and series was "added" in the last week (the apps' NEW badge covers 7 days), the rest
// weeks ago; dates count back from today, so "Recently added" never goes stale.
const NEW_EVERY = 6;

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const origin = url.origin;
    const path = url.pathname;
    const query = url.searchParams;

    if (path === "/" || path === "") {
      return Response.redirect(`${DATA.site}/`, 302);
    }

    const hls = path.match(/^\/hls\/([a-z0-9-]+)\.m3u8$/);
    if (hls) {
      return livePlaylist(hls[1]);
    }

    const stream = path.match(/^\/(live|movie|series)\/([^/]+)\/([^/]+)\/(\d+)\.(\w+)$/);
    if (stream) {
      const [, kind, username, password, id] = stream;
      if (username !== USERNAME || password !== PASSWORD) {
        return new Response("Forbidden", { status: 403 });
      }
      return streamRedirect(kind, Number(id), stream[5], origin, ctx);
    }

    const signedIn = query.get("username") === USERNAME && query.get("password") === PASSWORD;

    if (path === "/player_api.php") {
      if (!signedIn) {
        return json({ user_info: { auth: 0 } });
      }
      return json(playerApi(query.get("action") || "", query, origin));
    }

    if (path === "/xmltv.php") {
      return xml(guideXml());
    }

    if (path === "/get.php") {
      if (!signedIn) {
        return new Response("Forbidden", { status: 403 });
      }
      return text(m3u(origin), "audio/x-mpegurl");
    }

    return new Response("Not found", { status: 404 });
  },
};

// ---------------------------------------------------------------- API

function playerApi(action, query, origin) {
  const now = Math.floor(Date.now() / 1000);

  switch (action) {
    case "":
      return {
        user_info: {
          username: USERNAME, password: PASSWORD, message: "Dial demo playlist", auth: 1, status: "Active",
          exp_date: null, is_trial: "0", active_cons: "0", created_at: "1798761600", max_connections: "1",
          allowed_output_formats: ["m3u8", "ts"],
        },
        server_info: {
          url: new URL(origin).host, port: "443", https_port: "443", server_protocol: "https", rtmp_port: "0",
          timezone: "UTC", timestamp_now: now, time_now: new Date(now * 1000).toISOString().slice(0, 19).replace("T", " "),
        },
      };
    case "get_live_categories":
      return DATA.categories.live.map(category);
    case "get_vod_categories":
      return DATA.categories.movies.map(category);
    case "get_series_categories":
      return DATA.categories.series.map(category);
    case "get_live_streams":
      return DATA.live.filter(inCategory(query)).map((channel) => ({
        num: channel.num, name: channel.name, stream_type: "live", stream_id: channel.id, stream_icon: channel.logo,
        epg_channel_id: channel.key, added: addedAt(channel.num), category_id: String(channel.category), custom_sid: "",
        tv_archive: 0, direct_source: "", tv_archive_duration: 0,
      }));
    case "get_vod_streams":
      return DATA.movies.filter(inCategory(query)).map((movie) => ({
        num: movie.num, name: movie.name, stream_type: "movie", stream_id: movie.id, stream_icon: movie.poster,
        rating: "", rating_5based: 0, added: addedAt(movie.num), category_id: String(movie.category),
        container_extension: "mp4", custom_sid: "", direct_source: "",
      }));
    case "get_vod_info":
      return vodInfo(Number(query.get("vod_id")));
    case "get_series":
      return DATA.series.filter(inCategory(query)).map((series) => ({
        num: series.num, name: series.name, series_id: series.id, cover: series.cover, plot: series.plot, cast: "",
        director: "", genre: series.genre, releaseDate: "", last_modified: addedAt(series.num), rating: "", rating_5based: 0,
        backdrop_path: [series.backdrop], youtube_trailer: "", episode_run_time: "", category_id: String(series.category),
      }));
    case "get_series_info":
      return seriesInfo(Number(query.get("series_id")));
    case "get_simple_data_table":
    case "get_short_epg":
      return { epg_listings: listings(Number(query.get("stream_id")), action === "get_short_epg" ? Number(query.get("limit") || 4) : 0) };
    default:
      return [];
  }
}

function category(item) {
  return { category_id: String(item.id), category_name: item.name, parent_id: 0 };
}

function inCategory(query) {
  const wanted = query.get("category_id");
  return (item) => !wanted || String(item.category) === wanted;
}

function vodInfo(id) {
  const movie = DATA.movies.find((item) => item.id === id);
  if (!movie) {
    return { info: [], movie_data: {} };
  }

  return {
    info: {
      name: movie.name, movie_image: movie.poster, backdrop_path: [movie.backdrop], plot: movie.plot, description: movie.plot,
      genre: movie.genre, releasedate: "", duration_secs: movie.seconds, duration: clock(movie.seconds), rating: "",
    },
    movie_data: { stream_id: movie.id, name: movie.name, added: addedAt(movie.num), category_id: String(movie.category), container_extension: "mp4" },
  };
}

function seriesInfo(id) {
  const series = DATA.series.find((item) => item.id === id);
  if (!series) {
    return { seasons: [], info: [], episodes: {} };
  }

  return {
    seasons: [{ season_number: 1, name: "Season 1", episode_count: String(series.episodes.length), cover: series.cover }],
    info: {
      name: series.name, cover: series.cover, plot: series.plot, genre: series.genre, backdrop_path: [series.backdrop],
      category_id: String(series.category),
    },
    episodes: {
      1: series.episodes.map((episode) => ({
        id: String(episode.id), episode_num: episode.number, title: episode.title, container_extension: "mp4", season: 1,
        added: addedAt(series.num), info: { duration_secs: episode.seconds, duration: clock(episode.seconds), movie_image: episode.still, plot: "" },
      })),
    },
  };
}

// Unix seconds as a string, at midnight UTC: num 1, 7, 13 … 1–4 days ago, the others 12 days ago and older.
function addedAt(num) {
  const index = num - 1;
  const now = Math.floor(Date.now() / 1000);
  const today = now - (now % 86400);
  const days = index % NEW_EVERY === 0 ? 1 + index / NEW_EVERY : 10 + index * 2;
  return String(today - days * 86400);
}

function clock(seconds) {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  return [h, m, s].map((part) => String(part).padStart(2, "0")).join(":");
}

// ---------------------------------------------------------------- streams

function streamRedirect(kind, id, extension, origin, ctx) {
  if (kind === "live") {
    const channel = DATA.live.find((item) => item.id === id);
    if (!channel) {
      return new Response("Not found", { status: 404 });
    }

    return extension === "ts" ? liveTs(channel, ctx) : Response.redirect(`${origin}/hls/${channel.key}.m3u8`, 302);
  }

  if (kind === "movie") {
    const movie = DATA.movies.find((item) => item.id === id);
    return movie ? Response.redirect(movie.url, 302) : new Response("Not found", { status: 404 });
  }

  for (const series of DATA.series) {
    const episode = series.episodes.find((item) => item.id === id);
    if (episode) {
      return Response.redirect(episode.url, 302);
    }
  }

  return new Response("Not found", { status: 404 });
}

// The channel's position in its loop now: the loop's number since the Unix epoch and the segment playing.
function loopPosition(durations) {
  const loop = durations.reduce((sum, value) => sum + value, 0);
  const now = Date.now() / 1000;
  const cycle = Math.floor(now / loop);
  let offset = now - cycle * loop;
  let index = 0;

  while (index < durations.length - 1 && offset >= durations[index]) {
    offset -= durations[index];
    index += 1;
  }

  return { cycle, index };
}

// Live as one MPEG-TS response (Xtream's ".ts" address, as real providers serve it; ExoPlayer picks the format from the extension
// and doesn't follow a redirect to HLS). Starts at the 1-minute chunk playing now and streams the following chunks back to back.
// Chunks are consecutive pieces of one encode, so timestamps run on; the response ends at the end of the loop (timestamps would jump
// back to the start there) or after MAX_CHUNKS (the free plan allows 50 subrequests, each GitHub download is 2 with its redirect).
// The app then opens the channel again, as it does when a provider closes the connection.
const MAX_CHUNKS = 24;

function liveTs(channel, ctx) {
  const size = DATA.chunk_segments;
  const count = Math.ceil(channel.segments.length / size);
  const first = Math.floor(loopPosition(channel.segments).index / size);
  const last = Math.min(count, first + MAX_CHUNKS);
  const { readable, writable } = new TransformStream();

  const pump = (async () => {
    for (let chunk = first; chunk < last; chunk += 1) {
      const response = await fetch(`${DATA.releases}/live-${channel.key}/${channel.key}-c${String(chunk).padStart(3, "0")}.ts`);
      if (!response.ok || !response.body) {
        break;
      }

      await response.body.pipeTo(writable, { preventClose: true });
    }

    await writable.close();
  })().catch(() => writable.abort().catch(() => {}));

  ctx.waitUntil(pump);
  return new Response(readable, { headers: { "content-type": "video/mp2t", "cache-control": "no-store" } });
}

// Live: the channel's loop (segments with their durations) runs continuously since the Unix epoch; the playlist
// lists the last SEGMENT_WINDOW segments up to now, with a discontinuity where the loop starts again.
function livePlaylist(key) {
  const channel = DATA.live.find((item) => item.key === key);
  if (!channel) {
    return new Response("Not found", { status: 404 });
  }

  const durations = channel.segments;
  const count = durations.length;
  const { cycle, index } = loopPosition(durations);
  const current = cycle * count + index;
  const first = Math.max(0, current - SEGMENT_WINDOW + 1);
  const lines = ["#EXTM3U", "#EXT-X-VERSION:3", `#EXT-X-TARGETDURATION:${Math.ceil(Math.max(...durations))}`,
    `#EXT-X-MEDIA-SEQUENCE:${first}`, `#EXT-X-DISCONTINUITY-SEQUENCE:${Math.floor(first / count)}`];

  for (let sequence = first; sequence <= current; sequence += 1) {
    const segment = sequence % count;
    if (segment === 0 && sequence !== first) {
      lines.push("#EXT-X-DISCONTINUITY");
    }
    lines.push(`#EXTINF:${durations[segment].toFixed(3)},`, `${DATA.releases}/live-${channel.key}/${channel.key}-${String(segment).padStart(3, "0")}.ts`);
  }

  return text(lines.join("\n") + "\n", "application/vnd.apple.mpegurl", "no-cache");
}

// ---------------------------------------------------------------- guide

// 30-minute blocks aligned to the clock; titles cycle through the channel's programs, offset per channel so
// channels don't change titles in step.
function blocks(channel, from, to) {
  const result = [];
  const start = Math.floor(from / BLOCK_SECONDS) * BLOCK_SECONDS;

  for (let time = start; time < to; time += BLOCK_SECONDS) {
    const slot = Math.floor(time / BLOCK_SECONDS) + channel.num * 3;
    const program = channel.programs[slot % channel.programs.length];
    result.push({ start: time, stop: time + BLOCK_SECONDS, title: program.title, description: program.description });
  }

  return result;
}

function guideRange() {
  const now = Math.floor(Date.now() / 1000);
  const today = now - (now % 86400);
  return [today - GUIDE_DAYS_BEFORE * 86400, today + (GUIDE_DAYS_AFTER + 1) * 86400, now];
}

function listings(streamId, limit) {
  const channel = DATA.live.find((item) => item.id === streamId);
  if (!channel) {
    return [];
  }

  const [from, to, now] = guideRange();
  let items = blocks(channel, from, to);

  if (limit) {
    items = items.filter((block) => block.stop > now).slice(0, limit);
  }

  return items.map((block, index) => ({
    id: String(block.start / BLOCK_SECONDS), epg_id: String(channel.id), title: base64(block.title), lang: "en",
    start: stamp(block.start), end: stamp(block.stop), description: base64(block.description), channel_id: channel.key,
    start_timestamp: String(block.start), stop_timestamp: String(block.stop),
    now_playing: block.start <= now && now < block.stop ? 1 : 0, has_archive: 0,
  }));
}

function guideXml() {
  const [from, to] = guideRange();
  const parts = ['<?xml version="1.0" encoding="UTF-8"?>', '<tv generator-info-name="Dial demo">'];

  for (const channel of DATA.live) {
    parts.push(`<channel id="${escape(channel.key)}"><display-name>${escape(channel.name)}</display-name><icon src="${escape(channel.logo)}"/></channel>`);
  }

  for (const channel of DATA.live) {
    for (const block of blocks(channel, from, to)) {
      parts.push(`<programme start="${xmltvTime(block.start)}" stop="${xmltvTime(block.stop)}" channel="${escape(channel.key)}">` +
        `<title lang="en">${escape(block.title)}</title><desc lang="en">${escape(block.description)}</desc></programme>`);
    }
  }

  parts.push("</tv>");
  return parts.join("\n");
}

function stamp(seconds) {
  return new Date(seconds * 1000).toISOString().slice(0, 19).replace("T", " ");
}

function xmltvTime(seconds) {
  return new Date(seconds * 1000).toISOString().replace(/[-:T]/g, "").slice(0, 14) + " +0000";
}

function base64(value) {
  const bytes = new TextEncoder().encode(value);
  let binary = "";
  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }
  return btoa(binary);
}

function escape(value) {
  return String(value).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

// ---------------------------------------------------------------- M3U (get.php)

function m3u(origin) {
  const lines = [`#EXTM3U url-tvg="${origin}/xmltv.php?username=${USERNAME}&password=${PASSWORD}"`];

  for (const channel of DATA.live) {
    const group = DATA.categories.live.find((item) => item.id === channel.category).name;
    lines.push(`#EXTINF:-1 tvg-id="${channel.key}" tvg-name="${channel.name}" tvg-logo="${channel.logo}" group-title="${group}",${channel.name}`,
      `${origin}/live/${USERNAME}/${PASSWORD}/${channel.id}.ts`);
  }

  for (const movie of DATA.movies) {
    const group = DATA.categories.movies.find((item) => item.id === movie.category).name;
    lines.push(`#EXTINF:-1 tvg-name="${movie.name}" tvg-logo="${movie.poster}" group-title="${group}",${movie.name}`,
      `${origin}/movie/${USERNAME}/${PASSWORD}/${movie.id}.mp4`);
  }

  return lines.join("\n") + "\n";
}

// ---------------------------------------------------------------- responses

function json(value) {
  return new Response(JSON.stringify(value), { headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-cache" } });
}

function xml(value) {
  return new Response(value, { headers: { "content-type": "application/xml; charset=utf-8", "cache-control": "max-age=3600" } });
}

function text(value, type, cache = "max-age=300") {
  return new Response(value, { headers: { "content-type": `${type}; charset=utf-8`, "cache-control": cache } });
}
